var a=[{title:`De ce diferă umerii`,text:`Umărul are o amplitudine mare de mișcare și se bazează pe mulți mușchi ca să rămână stabil. Atingerea poziției deasupra capului, pozițiile adânci de împingere și mișcările rapide pot părea foarte diferit de la o persoană la alta. O mișcare restricționată sau dureroasă îți spune ceva despre ce exerciții să alegi. Nu dovedește că ai o anumită accidentare.`},{title:`Ajustează exercițiul`,text:`Dacă o împingere cu bara deasupra capului te deranjează, încearcă o împingere cu gantere în priză neutră, un ramat sprijinit sau o flotare la perete. Schimbă adâncimea sau direcția înainte să adaugi rezistență. Exercițiile de tragere sunt un partener bun pentru împingeri, dar niciun raport fix între împingere și tragere nu vindecă durerea de umăr.`},{title:`Control și expunere treptată`,text:`Cât înveți o mișcare, folosește repetări lente și controlate, o amplitudine confortabilă și sarcini ușoare. Dezvoltarea forței umărului poate cere o muncă treptat mai grea, dar acea progresie nu ar trebui să-ți agraveze simptomele. Forțarea unei întinderi prin durere sau testarea repetată a unor ridicări grele deasupra capului nu te va duce acolo mai repede.`},{title:`Semne de alarmă`,text:`Cere prompt sfat medical pentru durere severă după o cădere, un braț pe care nu-l poți mișca, o deformare vizibilă, o umflătură mare sau o amorțeală nouă care nu trece. Simptomele care nu se ameliorează trebuie și ele văzute de un specialist.`},{title:`Folosirea TrainUp`,text:`Adaugă umărul la limitări în Profil, cu note, și ține lista de echipamente la zi. Planul alege apoi doar exerciții care se potrivesc cu limitările, echipamentul, nivelul și coordonarea ta. Dacă un exercițiu doare în timpul unui antrenament, atinge „Simt durere” ca să-l încheie imediat. Rămâne în afara planurilor tale până îl reactivezi din Profil. Schimbarea exercițiilor în acest fel nu tratează sindromul de impingement, afecțiunile manșetei rotatorilor sau orice altă afecțiune specifică.`}];var r=[{label:`NHS: durerea de umăr și semnele de avertizare`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};